/* Original lessons, informed by the linked open-source topic indexes. No copied exercises. */
const opsExtended=[
 ['git','配置与语言','Git：先看变更再发布','Git 保存文件变更历史；仓库是项目记录，提交是一次有说明的变更快照。git status 看工作区状态，git diff 看未暂存的改动，git log 看提交历史。提交不等于发布，push 也不等于应用已经上线。','git status\ngit diff\ngit log --oneline -5\n本课只做理解题，以上命令不在教学终端执行。','改 Nginx 配置前后，适合怎样留证据？','记录版本、查看差异，发布后验证',['只把文件命名为最终版','直接强制推送所有内容'],'Git 管理变更，不自动保证配置正确或业务正常。','Git','关联：先在测试环境做配置校验，再按变更流程发布；敏感凭证不要提交。'],
 ['yaml','配置与语言','YAML：缩进就是层级','YAML 常用于 Compose、Kubernetes 和应用配置。键值用冒号分隔，缩进表示层级，列表项常以 - 开始。这里的 - 是列表标记，不是命令选项。通常用空格缩进，不用制表符；看起来相似的字符串和布尔值也要核对类型。','server:\n  port: 8080\n  enabled: true\n# port 是 server 下的字段；冒号后留空格。','YAML 中缩进的主要作用是什么？','表示数据的层级结构',['装饰，怎么缩进都一样','表示 Linux 管道'],'配置格式和命令语法不同，不能把 YAML 的 - 理解成命令参数。','YAML','关联：校验语法只证明格式可读，字段与业务含义还需要工具及应用验证。'],
 ['json','配置与语言','JSON 与 jq：按字段读接口数据','JSON 用对象和数组表示结构化数据：对象用花括号，字段名通常用双引号，数组用方括号。jq 是处理 JSON 的命令工具；.status 表示取 status 字段。别直接对复杂 JSON 用按空格提列的 awk。','{"status":"ok","latency_ms":23}\n示意：jq .status health.json → "ok"\n本课理解练习，不模拟 jq 执行。','读取 JSON 的 status 字段，较合适的工具是什么？','支持 JSON 字段查询的 jq',['无条件取第 4 个空格分隔片段','只看文件大小'],'结构化格式应按字段和层级处理。','JSON','关联：Python 的 json.loads 也可解析 JSON；网页已有真实运行的 Python 课堂。'],
 ['ansible','自动化与交付','Ansible：批量操作先限定范围','Ansible 使用清单列出目标主机，通过任务描述检查或更改状态。清单不是执行结果，检查模式也不能保证所有任务都无影响。先在测试目标验证，明确权限和目标数量，再逐步扩大范围。','目标清单 → 测试环境 → 限定目标 → 检查差异 → 执行 → 验证\nplaybook 是任务文件；inventory 是主机清单。','批量修改之前应该优先确认什么？','实际目标、权限、测试结果和回退方法',['直接对全部主机执行','只确认文件名字好看'],'自动化会放大错误，范围必须明确。','Ansible','关联：先把单机操作和验收写清楚，再自动化；不是靠把命令复制一百次建立可靠流程。'],
 ['disk-case','棘手场景','磁盘满了：先分清容量与 inode','df 看文件系统，du 看目录占用，两者可能不一致。inode 是文件系统管理文件对象的记录，很多小文件也可能耗尽它。还有已删除但仍被进程打开的文件会占空间。先找证据，再选择轮转、清理或扩容，避免随意删数据库文件。','容量 → df -h\ninode → df -i\n目录占用 → du（注意扫描开销）\n打开但已删除文件 → 查进程打开文件\n这里是调查流程，不执行真实清理。','df 和 du 不一致时，合理做法是？','继续检查挂载点、权限和已删除仍打开的文件',['直接删整个 /var','认定 df 一定出错'],'工具观察对象和口径不同，需要解释差异。','inode','关联：清理前确认归属与保留策略，数据库、备份和活跃日志有不同处理规则。'],
 ['cert-case','棘手场景','证书与时间：连接成功也可能不可信','HTTPS 证书帮助客户端确认服务器身份。到期、域名不匹配、证书链不完整、系统时间错误都可能导致校验失败。关闭验证只能掩盖问题；应按域名、有效期、证书链和时间查证。','访问域名 → 证书包含该域名？ → 是否过期？ → 链是否可信？ → 系统时间是否正确？','证书校验失败时，长期解决方式是？','修正证书、域名、证书链或系统时间问题',['永久关闭所有验证','把报错日志删掉'],'加密与身份验证都需要正确配置。','证书','关联：页面显示安全连接也不意味着业务权限正确；登录与授权是另一层。'],
 ['latency-case','棘手场景','服务很慢：沿请求链路量时间','响应慢不等于 CPU 高。请求可能在入口排队、应用线程池等待、数据库锁等待、外部依赖超时或网络重传中耗时。用请求标识关联时间、日志和指标；先限定慢请求窗口，再逐层比较耗时。','同一 request_id：入口耗时 → 应用耗时 → SQL 耗时 → 外部调用耗时\n先看证据，再决定是否重启或扩容。','慢请求排查应该怎样开始？','限定请求与时间窗口，关联各层耗时',['先重启全部服务','只看一张 CPU 截图就确认根因'],'总耗时要拆到链路里，单一指标不足以解释根因。','延迟','关联：数据库慢查询、锁与连接池是后续专项；不把应用活着等同于应用能快速完成业务。'],
 ['backup-case','棘手场景','备份能恢复才算验证','备份文件存在不代表可恢复。需要核对时间点、完整性、加密密钥和依赖，再在隔离环境恢复并验收关键数据。恢复目标时间与允许数据丢失量是业务要求；不要在生产直接试验覆盖恢复。','备份记录 → 隔离恢复 → 数据一致性 → 关键查询 → 记录耗时与结果','验证备份较可靠的方法是什么？','在隔离环境实际恢复并验证数据',['只看文件名带 backup','只看文件比昨天大'],'文件存在是证据之一，实际恢复才验证可用性。','恢复演练','关联：版本回退不会自动恢复数据库与持久卷数据。']
];
hubSources.opswork=['开源运维练习主题索引 · DevOps Exercises','https://github.com/bregman-arie/devops-exercises'];
opsExtended.forEach(r=>{addHubLesson('opswork',...r);const c=hubCurriculum.opswork.at(-1);c.tasks=c.tasks.slice(0,1);c.body.push('这是原创中文理解课；借鉴开源项目的主题范围，未复制其题目。命令示例是否可执行以本课说明为准。');});
Object.assign(beginnerTerms,{Git:'记录项目文件变更的版本管理工具。提交保存一次快照；提交、推送和上线是不同动作。',YAML:'常见配置格式，缩进表达层级。配置中的 - 常是列表标记，与命令的选项不同。',JSON:'结构化数据格式，对象用花括号，数组用方括号；适合用专门解析器按字段读取。',Ansible:'面向多个目标执行任务的自动化工具，先明确清单和权限，再测试与验证。',inode:'文件系统用于记录文件对象属性的结构。容量未满也可能因为 inode 耗尽而无法创建文件。',证书:'帮助客户端核验服务器身份的电子凭证，要核对域名、有效期和信任链。',延迟:'一次操作从开始到完成花的时间。整体变慢需要分解到入口、应用、数据库和外部依赖。',恢复演练:'在隔离环境实际使用备份恢复并核验数据，证明备份可以使用。'});
Object.assign(beginnerTerms,{变量:'程序中用来引用一个值的名字。Python 里 x = 3 把名字 x 绑定到整数 3，= 是赋值，不是比较。',字符串:'一段文本，Python 通常用单引号或双引号包围；数字文本 "3" 与整数 3 不是同一种值。',函数:'有名字、可以调用的一段处理逻辑。参数给输入，return 给返回值；print 显示文字与返回值是两回事。',参数:'输入给命令或函数的信息。命令选项可改变行为，位置参数给对象；Python 函数参数写在括号内。',循环:'重复执行代码。Python 的 for 通常逐个处理集合中的元素，while 在条件为真时重复；缩进决定重复哪些代码。',条件:'决定是否执行某段逻辑的判断。Python 的 if 判断条件，== 比较，= 赋值；两者不能交换。',列表:'按顺序保存多个值的 Python 容器，常用方括号，例如 [200, 500]；索引从 0 开始。',字典:'按键寻找值的 Python 容器，例如 {"status": "ok"}；用键访问，不是靠空格位置。',返回值:'函数调用交回的结果，Python 用 return 给出。显示在屏幕上不等于返回给调用者。',假名:'日语表音文字，平假名与片假名通常表示同样的音，使用场景不同；汉字另有读音。',助词:'日语中连接词语并提示句子关系的小词，例如 は 提示话题、を 标记常见宾语，不能只按单个汉字直译。',五十音:'日语基础假名的排列方式，用行列整理读音；实际还有浊音、半浊音和拗音，需要逐步学习。',活用:'日语词语根据语法功能改变形式，例如动词的否定、过去和礼貌形式；先看原形再看变化规则。',Agent:'可以围绕任务调用工具、处理反馈的 AI 应用。能生成计划不代表动作已经实际执行，仍需记录和验证。',RAG:'先检索相关资料，再让模型结合资料回答的方法。检索到的文档可能有错误，需要检查来源和支持关系。',MCP:'让应用以统一协议提供工具与资源的方式。接入不等于自动获得所有权限，调用仍要遵守授权边界。',上下文:'当前判断使用的输入信息，例如对话、任务、资料和工具结果。信息多不等于一定准确，要保留来源。',幂等:'同一操作重复执行仍得到相同业务效果的性质；例如用固定请求标识防止重试生成重复订单。'});
